<?php $flow = ['placed', 'confirmed', 'processing', 'packed', 'shipped', 'delivered']; ?>
<section class="max-w-3xl mx-auto px-4 py-10"><h1 class="section-title text-3xl">Track Your Order</h1><p class="muted mt-4">Enter your order reference and the mobile number used at checkout.</p>
  <form method="post" action="<?= e(url('/track')) ?>" class="card p-5 mt-6 grid sm:grid-cols-[1fr_1fr_auto] gap-3 items-end"><?= csrf_field() ?>
    <div><label class="label" for="reference">Order reference</label><input class="input font-mono uppercase" id="reference" name="reference" placeholder="FC-XXXXX-XXXXX" required maxlength="24" value="<?= e($_POST['reference'] ?? ($_GET['ref'] ?? '')) ?>"></div>
    <div><label class="label" for="mobile">Mobile number</label><input class="input" id="mobile" name="mobile" type="tel" inputmode="numeric" required maxlength="13" value="<?= e($_POST['mobile'] ?? '') ?>"></div>
    <button class="btn btn-primary"><?= icon('search', 'w-4 h-4') ?> Track</button></form>
  <?php if ($error): ?><div role="alert" class="mt-4 rounded-xl bg-red-50 border border-red-200 text-red-800 p-4 text-sm"><?= e($error) ?></div><?php endif; ?>
  <?php if ($o): $cancelled = $o['status'] === 'cancelled'; $idx = array_search($o['status'], $flow); ?>
  <div class="card p-5 md:p-6 mt-6"><div class="flex flex-wrap justify-between gap-3"><div><div class="muted text-sm">Order</div><b class="font-mono text-lg"><?= e($o['reference']) ?></b></div><div class="text-right"><?= status_badge($o['status']) ?><div class="text-xs muted mt-1">Placed <?= e(date('d M Y, h:i A', strtotime($o['created_at']))) ?></div></div></div>
    <?php if ($cancelled): ?><p class="mt-5 rounded-xl bg-red-50 text-red-800 p-3 text-sm">This order was cancelled.</p><?php else: ?>
    <div class="steps mt-6"><?php foreach ($flow as $k => $s): ?><div class="st <?= $k <= $idx ? 'done' : '' ?>"><b><?= $k <= $idx ? '✓' : $k + 1 ?></b><?= e(order_statuses()[$s]) ?></div><?php endforeach; ?></div><?php endif; ?>
    <?php if ($o['tracking_info']): ?><p class="mt-4 text-sm rounded-xl tint-secondary p-3"><b>Tracking info:</b> <?= e($o['tracking_info']) ?></p><?php endif; ?>
    <div class="grid sm:grid-cols-2 gap-6 mt-6"><div><h2 class="font-bold mb-3">Status history</h2><ul class="timeline text-sm"><?php foreach (array_reverse($o['history']) as $h): ?><li><b><?= e(order_statuses()[$h['status']] ?? $h['status']) ?></b><span class="block text-xs muted"><?= e(date('d M Y, h:i A', strtotime($h['created_at']))) ?></span><?php if ($h['note'] && !str_starts_with($h['note'], 'Order placed by')): ?><span class="block muted"><?= e($h['note']) ?></span><?php endif; ?></li><?php endforeach; ?></ul></div>
      <div><h2 class="font-bold mb-3">Order summary</h2><ul class="text-sm space-y-1"><?php foreach ($o['items'] as $i): ?><li class="flex justify-between gap-2"><span><?= (int)$i['quantity'] ?> × <?= e($i['name']) ?></span><span><?= money($i['line_total']) ?></span></li><?php endforeach; ?></ul><div class="flex justify-between font-bold border-t border-black/10 mt-3 pt-2"><span>Total</span><span><?= money($o['total']) ?></span></div><p class="text-xs muted mt-2">Payment: <b class="capitalize"><?= e($o['payment_status']) ?></b></p></div></div></div>
  <?php endif; ?></section>
